data class User(val name: String, val isOnline: Boolean, val lastSeenAt: Instant)

fun collectActiveUsers(users: List<User>, cutoff: Instant): List<String> {
    return users
        .filter { it.isOnline && it.lastSeenAt > cutoff }
        .map { it.name }
}

fun clampScore(score: Int, minimum: Int, maximum: Int): Int {
    return when {
        score < minimum -> minimum
        score > maximum -> maximum
        else -> score
    }
}

fun groupPostsByTag(posts: List<Post>): Map<String, List<String>> {
    return posts
        .flatMap { post -> post.tags.map { tag -> tag to post.slug } }
        .groupBy({ it.first }, { it.second })
}

suspend fun loadProjectSummary(client: HttpClient, projectId: String): String {
    val response = client.get("/api/projects/$projectId")

    if (!response.status.isSuccess()) {
        throw IllegalStateException("Failed to load project summary")
    }

    val project = response.body<Project>()
    return "${project.name}:${project.branch}".lowercase()
}

sealed interface RouteLanguage {
    object Kotlin : RouteLanguage
    object Java : RouteLanguage
    object Python : RouteLanguage
}

fun parseLanguage(value: String?): RouteLanguage = when (value) {
    "kotlin" -> RouteLanguage.Kotlin
    "java" -> RouteLanguage.Java
    "python" -> RouteLanguage.Python
    else -> RouteLanguage.Kotlin
}

fun String.toSlug(): String {
    return this.trim()
        .lowercase()
        .replace(Regex("[^a-z0-9]+"), "-")
        .trim('-')
}

val slug = "  Hello, World!  ".toSlug()

inline fun <T> tryCatching(block: () -> T): Result<T> {
    return try {
        Result.success(block())
    } catch (error: Throwable) {
        Result.failure(error)
    }
}

val parsed = tryCatching { Json.decodeFromString<Config>(raw) }

class ScoreBuilder {
    private var name: String = "anon"
    private var value: Int = 0

    fun named(name: String) = apply { this.name = name }
    fun worth(value: Int) = apply { this.value = value }
    fun build() = Score(name = name, value = value)
}

val score = ScoreBuilder().named("ada").worth(120).build()

class ConfigStore(private val path: Path) {
    val config: Config by lazy {
        Files.readString(path).let { raw ->
            Json.decodeFromString<Config>(raw)
        }
    }
}

fun chunked(items: List<Int>, size: Int): List<List<Int>> {
    require(size > 0) { "size must be positive" }

    return items.windowed(size = size, step = size, partialWindows = true)
}

val batches = chunked((1..10).toList(), 3)
